:root {
  /* Colors */
  --color-linen-canvas: #fafafa;
  --color-paper-white: #ffffff;
  --color-fog-surface: #f5f5f5;
  --color-jet-action: #000000;
  --color-onyx-ink: #171717;
  --color-graphite-ink: #262626;
  --color-iron-nav: #404040;
  --color-slate-caption: #737373;
  --color-ash-muted: #a3a3a3;
  --color-mist-border: #e5e5e5;
  --color-ember-links: #fb923c;
  --color-sprout-analytics: #4ade80;
  --color-lavender-partners: #c084fc;

  /* Typography — Font Families */
  --font-satoshi: "Satoshi", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.333;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.429;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.556;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.333;
  --tracking-subheading: 0px;
  --text-heading-sm: 30px;
  --leading-heading-sm: 1.375;
  --tracking-heading-sm: 0px;
  --text-heading: 40px;
  --leading-heading: 1;
  --tracking-heading: 0px;
  --text-display: 48px;
  --leading-display: 1;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-56: 56px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-160: 160px;

  /* Layout */
  --layout-max-width: 1080px;
  --layout-section-gap: 96px;
  --layout-card-padding: 16px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 8px;
  --radius-nav: 8px;
  --radius-cards: 8px;
  --radius-tags: 8px;
  --radius-images: 8px;
  --radius-inputs: 6px;
  --radius-innerTiles: 6px;
  --radius-smallElements: 4px;
  --radius-smallCards: 12px;
  --radius-sections: 16px;
  --radius-alertBanners: 12px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0px 1px 2px 0px rgba(0, 0, 0, 0.05);
  --shadow-subtle-2: inset 0px 2px 6px 0px rgba(0, 0, 0, 0.2);
  --shadow-sm: 0px 0px 0px 4px rgba(0, 0, 0, 0.1);
  --shadow-md: 0px 4px 6px -1px rgba(0, 0, 0, 0.1), 0px 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0px 10px 15px -3px rgba(0, 0, 0, 0.1), 0px 4px 6px -4px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0px 20px 20px 0px rgba(0, 0, 0, 0.09);

  /* Surfaces */
  --surface-linen-canvas: #fafafa;
  --surface-fog-surface: #f5f5f5;
  --surface-paper-white: #ffffff;
  --surface-graphite-ink: #262626;
}

